import calendar, random
from datetime import datetime, date, timedelta
from dateutil.relativedelta import relativedelta

def ref(dt, years=0, months=0, days=0, hours=0, minutes=0, seconds=0,
        microseconds=0, weeks=0):
    year = dt.year + years
    month = dt.month + months
    while month > 12:
        year += 1; month -= 12
    while month < 1:
        year -= 1; month += 12
    day = min(calendar.monthrange(year, month)[1], dt.day)
    r = dt.replace(year=year, month=month, day=day)
    return r + timedelta(days=days + 7*weeks, hours=hours, minutes=minutes,
                         seconds=seconds, microseconds=microseconds)

random.seed(1)
bad = []
for _ in range(20000):
    kw = {}
    for k in ['years','months','days','hours','minutes','seconds','microseconds','weeks']:
